value.serialGenerator:
function () {
    var serial_select = this.getFieldValue('serial_select');
    var code = '';
    Blockly.Arduino.definitions_['include_HardwareSerial'] = '#include "HardwareSerial.h"';
    var dropdown_tx = this.getFieldValue('TX');
    var dropdown_rx = this.getFieldValue('RX');
    pin_digital.forEach(element => {
        if (dropdown_tx == element[0]) {
            dropdown_tx = element[1]
        }
        if (dropdown_rx == element[0]) {
            dropdown_rx = element[1]
        }
    });
    if (serial_select == 'Serial') {
        // Blockly.Arduino.setups_['setPinFun_13'] = 'setPinFun(13,SECOND_FUNCTION);';
        // Blockly.Arduino.setups_['setPinFun_14'] = 'setPinFun(14,SECOND_FUNCTION);';
        code += 'setPinFun(13,SECOND_FUNCTION);\n' +
            'setPinFun(14,SECOND_FUNCTION);\n';
    } else if (serial_select == 'Serial1') {
        if (dropdown_tx == '7') {
            // Blockly.Arduino.setups_['setPinFun_7'] = 'setPinFun(15,THIRD_FUNCTION);';
            code += 'setPinFun(7,THIRD_FUNCTION);\n';
        } else if (dropdown_tx == '15') {
            // Blockly.Arduino.setups_['setPinFun_15'] = 'setPinFun(15,SECOND_FUNCTION);';
            code += 'setPinFun(15,SECOND_FUNCTION);\n';
        } else {
            // Blockly.Arduino.setups_['setPinFun_' + dropdown_tx] = 'setPinFun(' + dropdown_tx + ',FORTH_FUNCTION);';
            code += 'setPinFun(' + dropdown_tx + ',FORTH_FUNCTION);\n';
        }
        if (dropdown_rx == '8') {
            // Blockly.Arduino.setups_['setPinFun_8'] = 'setPinFun(8,THIRD_FUNCTION);';
            code += 'setPinFun(8,THIRD_FUNCTION);\n';
        } else if (dropdown_rx == '16') {
            // Blockly.Arduino.setups_['setPinFun_16'] = 'setPinFun(16,SECOND_FUNCTION);';
            code += 'setPinFun(16,SECOND_FUNCTION);\n';
        } else {
            // Blockly.Arduino.setups_['setPinFun_' + dropdown_rx] = 'setPinFun(' + dropdown_rx + ',FORTH_FUNCTION);';
            code += 'setPinFun(' + dropdown_rx + ',FORTH_FUNCTION);\n';
        }
    } else if (serial_select == 'Serial2') {
        if (dropdown_tx == '9') {
            // Blockly.Arduino.setups_['setPinFun_9'] = 'setPinFun(9,THIRD_FUNCTION);';
            code += 'setPinFun(9,THIRD_FUNCTION);\n';
        } else if (dropdown_tx == '14') {
            // Blockly.Arduino.setups_['setPinFun_14'] = 'setPinFun(14,FIFTH_FUNCTION);';
            code += 'setPinFun(14,FIFTH_FUNCTION);\n';
        } else {
            // Blockly.Arduino.setups_['setPinFun_' + dropdown_tx] = 'setPinFun(' + dropdown_tx + ',FORTH_FUNCTION);';
            code += 'setPinFun(' + dropdown_tx + ',FORTH_FUNCTION);\n';
        }
        if (dropdown_rx == '10') {
            // Blockly.Arduino.setups_['setPinFun_10'] = 'setPinFun(10,THIRD_FUNCTION);';
            code += 'setPinFun(10,THIRD_FUNCTION);\n';
        } else {
            // Blockly.Arduino.setups_['setPinFun_' + dropdown_rx] = 'setPinFun(' + dropdown_rx + ',FORTH_FUNCTION);';
            code += 'setPinFun(' + dropdown_rx + ',FORTH_FUNCTION);\n';
        }
    }
    var content = Blockly.Arduino.valueToCode(this, 'CONTENT', Blockly.Arduino.ORDER_ATOMIC);
    // Blockly.Arduino.setups_['setup_serial_' + serial_select] = serial_select + '.begin(' + content + ');';
    code += serial_select + '.begin(' + content + ');\n';
    return code;
}

value.baudGenerator:
function () {
    var code = this.getFieldValue('baud');
    return [code, Blockly.Arduino.ORDER_ATOMIC];
}
